declare packet jsonb=$payload${"patches":[{"id":"16692185-16a4-53c3-b1e4-547f7db14ef9","before_hash":"f248dec091485acc5249ad42b7886f15","before_question":{"id":"16692185-16a4-53c3-b1e4-547f7db14ef9","stem":"Brad’s average on his last three math tests was 76. What grade should he earn on the fourth test to have an average of 80?","type":"mcq","topic":"Statistics and data analysis","assets":{"source":"teacher_uploaded_notes_20261005","source_item":2,"source_page":10,"answer_review":"2026-10-05-independent-solution-and-image-check","release_batch":"20261005_uploaded_notes_est_bank","source_sha256":"c8866e74eb87ce3401c5e3bd6ea7a7717f889dc70ec6398eedc2d0e89e4ed62c","lesson_subtopic":"Mean and averages","source_document":"Notes_261005_140129.pdf","verified_release":"20261005_uploaded_notes_est_bank","curriculum_lesson":"Statistics and data analysis","verification_note":"Transcribed from the uploaded page image; independently solved. The student-facing stem preserves all needed source givens.","lesson_original_topic":"Statistics and data analysis","lesson_taxonomy_version":"20260929"},"choices":[{"key":"A","text":"88"},{"key":"B","text":"90"},{"key":"C","text":"92"},{"key":"D","text":"94"}],"track_id":"est","created_at":"2026-10-05T12:13:59.985454+00:00","difficulty":"easy"},"before_key":{"question_id":"16692185-16a4-53c3-b1e4-547f7db14ef9","correct":"C","explanation":"The first three scores total 3×76=228. A four-test average of 80 requires a total of 320, so the fourth score must be 320−228=92."},"stem":"Brad’s average on his last three math tests was 76. What grade should he earn on the fourth test to have an average of 80?","asset_patch":{"clean_source_evidence":{"file":"Notes_261005_145856.pdf","sha256":"1e6cf0ca15d3f96ff5491f27decb93ec3bf685d2ce26d134b64feb50824abb8e","library_file_id":"libfile_8903da570ab48191ad8df88cbba4b6ce","pages":12,"physical_page":10,"block":2,"release":"20261005-clean-notes","decision":"Complete wording, choices and independently solved answer confirmed from clean source."}}},{"id":"38106f66-a183-53bb-87b9-0a53da3d59fe","before_hash":"57a59fdaaa2f6c3c151f377d44238dfb","before_question":{"id":"38106f66-a183-53bb-87b9-0a53da3d59fe","stem":"O is the center of a circle, and T is outside the circle. The tangent segment from the point of tangency to T has length 7, and OT = 10. If the area of the circle is kπ, what is k?","type":"mcq","topic":"Circles","assets":{"source":"teacher_uploaded_notes_20261005","source_item":2,"source_page":2,"answer_review":"2026-10-05-independent-solution-and-image-check","release_batch":"20261005_uploaded_notes_est_bank","source_sha256":"c8866e74eb87ce3401c5e3bd6ea7a7717f889dc70ec6398eedc2d0e89e4ed62c","lesson_subtopic":"Circle theorems and area","source_document":"Notes_261005_140129.pdf","verified_release":"20261005_uploaded_notes_est_bank","curriculum_lesson":"Circles","verification_note":"Transcribed from the uploaded page image; independently solved. The student-facing stem preserves all needed source givens.","lesson_original_topic":"Circles","lesson_taxonomy_version":"20260929"},"choices":[{"key":"A","text":"51"},{"key":"B","text":"49"},{"key":"C","text":"√51"},{"key":"D","text":"60"}],"track_id":"est","created_at":"2026-10-05T12:13:59.985454+00:00","difficulty":"medium"},"before_key":{"question_id":"38106f66-a183-53bb-87b9-0a53da3d59fe","correct":"A","explanation":"The radius to the point of tangency is perpendicular to the tangent. Thus r²+7²=10², so r²=51. The area is 51π, giving k=51."},"stem":"O is the center of a circle, and T is outside the circle. The tangent segment from the point of tangency to T has length 7, and OT = 10. If the area of the circle is kπ, what is k?","asset_patch":{"clean_source_evidence":{"file":"Notes_261005_145856.pdf","sha256":"1e6cf0ca15d3f96ff5491f27decb93ec3bf685d2ce26d134b64feb50824abb8e","library_file_id":"libfile_8903da570ab48191ad8df88cbba4b6ce","pages":12,"physical_page":2,"block":2,"release":"20261005-clean-notes","decision":"Complete wording, choices and independently solved answer confirmed from clean source."}}},{"id":"40a2b239-15ea-5538-a297-339b61ee30ef","before_hash":"c2f28433ea2ad4df5492dc0173d279fd","before_question":{"id":"40a2b239-15ea-5538-a297-339b61ee30ef","stem":"The lines y = m₁x + 4 and y = m₂x + 3 intersect to the right of the y-axis if and only if which condition holds?","type":"mcq","topic":"Linear functions and slope","assets":{"source":"teacher_uploaded_notes_20261005","source_item":1,"source_page":5,"answer_review":"2026-10-05-independent-solution-and-image-check","release_batch":"20261005_uploaded_notes_est_bank","source_sha256":"c8866e74eb87ce3401c5e3bd6ea7a7717f889dc70ec6398eedc2d0e89e4ed62c","lesson_subtopic":"Intersection and slope conditions","source_document":"Notes_261005_140129.pdf","verified_release":"20261005_uploaded_notes_est_bank","curriculum_lesson":"Linear functions and slope","verification_note":"Transcribed from the uploaded page image; independently solved. The student-facing stem preserves all needed source givens.","lesson_original_topic":"Linear functions and slope","lesson_taxonomy_version":"20260929"},"choices":[{"key":"A","text":"m₁ = m₂"},{"key":"B","text":"m₁ < m₂"},{"key":"C","text":"m₁ > m₂"},{"key":"D","text":"m₁ + m₂ = 0"},{"key":"E","text":"m₁ ≠ m₂"}],"track_id":"est","created_at":"2026-10-05T12:13:59.985454+00:00","difficulty":"medium"},"before_key":{"question_id":"40a2b239-15ea-5538-a297-339b61ee30ef","correct":"B","explanation":"At the intersection, m₁x+4=m₂x+3, so x=−1/(m₁−m₂). For x>0, the denominator must be negative. Therefore m₁−m₂<0, or m₁<m₂."},"stem":"The lines y = m₁x + 4 and y = m₂x + 3 intersect to the right of the y-axis if and only if which condition holds?","asset_patch":{"clean_source_evidence":{"file":"Notes_261005_145856.pdf","sha256":"1e6cf0ca15d3f96ff5491f27decb93ec3bf685d2ce26d134b64feb50824abb8e","library_file_id":"libfile_8903da570ab48191ad8df88cbba4b6ce","pages":12,"physical_page":5,"block":1,"release":"20261005-clean-notes","decision":"Complete wording, choices and independently solved answer confirmed from clean source."}}},{"id":"4303079b-1b94-558e-951e-b84b32c61fe4","before_hash":"db0dc475a0b61e409e24260a570ada4f","before_question":{"id":"4303079b-1b94-558e-951e-b84b32c61fe4","stem":"In the xy-plane, x² + y² − 2kx + 4y − 3k² = 0 is the equation of a circle with center (1/2, −2) and radius √5. What is k?\nRecord your answer as a number.","type":"grid_in","topic":"Circles","assets":{"source":"teacher_uploaded_notes_20261005","source_item":2,"source_page":11,"answer_review":"2026-10-05-independent-solution-and-image-check","release_batch":"20261005_uploaded_notes_est_bank","source_sha256":"c8866e74eb87ce3401c5e3bd6ea7a7717f889dc70ec6398eedc2d0e89e4ed62c","lesson_subtopic":"Circle equations","source_document":"Notes_261005_140129.pdf","verified_release":"20261005_uploaded_notes_est_bank","curriculum_lesson":"Circles","verification_note":"Transcribed from the uploaded page image; independently solved. The student-facing stem preserves all needed source givens.","lesson_original_topic":"Circles","lesson_taxonomy_version":"20260929"},"choices":[],"track_id":"est","created_at":"2026-10-05T12:13:59.985454+00:00","difficulty":"medium"},"before_key":{"question_id":"4303079b-1b94-558e-951e-b84b32c61fe4","correct":"0.5","explanation":"In standard form, the center is (k, −2), so k=1/2. Completing the square gives r²=4k²+4=5, which is consistent with k=1/2."},"stem":"In the xy-plane, x² + y² − 2kx + 4y − 3k² = 0 is the equation of a circle with center (1/2, −2) and radius √5. What is k?\nRecord your answer as a number.","asset_patch":{"clean_source_evidence":{"file":"Notes_261005_145856.pdf","sha256":"1e6cf0ca15d3f96ff5491f27decb93ec3bf685d2ce26d134b64feb50824abb8e","library_file_id":"libfile_8903da570ab48191ad8df88cbba4b6ce","pages":12,"physical_page":11,"block":2,"release":"20261005-clean-notes","decision":"Source-equivalent duplicate; retain original ID/key/history under hold."},"release_hold_reason":"Duplicate of reviewed question 8326565d-6af6-507f-9e4f-f07daf00e3a5","duplicate_of":"8326565d-6af6-507f-9e4f-f07daf00e3a5"}},{"id":"8718178a-37c6-5acd-8f8e-dd9449825645","before_hash":"4651c28c7960bde5222342a8cc8b3b03","before_question":{"id":"8718178a-37c6-5acd-8f8e-dd9449825645","stem":"On a map, 1 cm represents 25 km. If two cities are 7.5 cm apart on the map, what is the actual distance between them, in kilometers?\nRecord your answer as a number.","type":"grid_in","topic":"Ratios, percentages and unit conversion","assets":{"source":"teacher_uploaded_notes_20261005","source_item":1,"source_page":12,"answer_review":"2026-10-05-independent-solution-and-image-check","release_batch":"20261005_uploaded_notes_est_bank","source_sha256":"c8866e74eb87ce3401c5e3bd6ea7a7717f889dc70ec6398eedc2d0e89e4ed62c","lesson_subtopic":"Scale and unit rates","source_document":"Notes_261005_140129.pdf","verified_release":"20261005_uploaded_notes_est_bank","curriculum_lesson":"Ratios, percentages and unit conversion","verification_note":"Transcribed from the uploaded page image; independently solved. The student-facing stem preserves all needed source givens.","lesson_original_topic":"Ratios, percentages and unit conversion","lesson_taxonomy_version":"20260929"},"choices":[],"track_id":"est","created_at":"2026-10-05T12:13:59.985454+00:00","difficulty":"easy"},"before_key":{"question_id":"8718178a-37c6-5acd-8f8e-dd9449825645","correct":"187.5","explanation":"Multiply the map distance by the scale: 7.5×25=187.5 km."},"stem":"On a map, 1 cm represents 25 km. If two cities are 7.5 cm apart on the map, what is the actual distance between them, in kilometers?\nRecord your answer as a number.","asset_patch":{"clean_source_evidence":{"file":"Notes_261005_145856.pdf","sha256":"1e6cf0ca15d3f96ff5491f27decb93ec3bf685d2ce26d134b64feb50824abb8e","library_file_id":"libfile_8903da570ab48191ad8df88cbba4b6ce","pages":12,"physical_page":12,"block":1,"release":"20261005-clean-notes","decision":"Complete wording, choices and independently solved answer confirmed from clean source."}}},{"id":"bbba6fb0-9daa-5cf1-9374-3f80b7460810","before_hash":"5fb2a0d1e3d9005a01d186d1b03b6ead","before_question":{"id":"bbba6fb0-9daa-5cf1-9374-3f80b7460810","stem":"From 2018 to 2019, the amount in Julia’s bank account increased by 22.5% to $14,325. To the nearest dollar, what was the amount in her account in 2018?","type":"mcq","topic":"Ratios, percentages and unit conversion","assets":{"source":"teacher_uploaded_notes_20261005","source_item":1,"source_page":11,"answer_review":"2026-10-05-independent-solution-and-image-check","release_batch":"20261005_uploaded_notes_est_bank","source_sha256":"c8866e74eb87ce3401c5e3bd6ea7a7717f889dc70ec6398eedc2d0e89e4ed62c","lesson_subtopic":"Percent increase and reverse calculation","source_document":"Notes_261005_140129.pdf","verified_release":"20261005_uploaded_notes_est_bank","curriculum_lesson":"Ratios, percentages and unit conversion","verification_note":"Transcribed from the uploaded page image; independently solved. The student-facing stem preserves all needed source givens.","lesson_original_topic":"Ratios, percentages and unit conversion","lesson_taxonomy_version":"20260929"},"choices":[{"key":"A","text":"$11,694"},{"key":"B","text":"$14,010"},{"key":"C","text":"$11,102"},{"key":"D","text":"$12,775"}],"track_id":"est","created_at":"2026-10-05T12:13:59.985454+00:00","difficulty":"medium"},"before_key":{"question_id":"bbba6fb0-9daa-5cf1-9374-3f80b7460810","correct":"A","explanation":"If P was the 2018 balance, then 1.225P=14,325. Thus P=14,325/1.225≈11,693.88, which rounds to $11,694."},"stem":"From 2018 to 2019, the amount in Julia’s bank account increased by 22.5% to $14,325. To the nearest dollar, what was the amount in her account in 2018?","asset_patch":{"clean_source_evidence":{"file":"Notes_261005_145856.pdf","sha256":"1e6cf0ca15d3f96ff5491f27decb93ec3bf685d2ce26d134b64feb50824abb8e","library_file_id":"libfile_8903da570a