and in 2009 she earned 4% more than in 2008. If Zinah earned y times as much in 2009 as in 2007, what is y?","asset_patch":{"clean_source_evidence":{"file":"Notes_261005_145856.pdf","sha256":"1e6cf0ca15d3f96ff5491f27decb93ec3bf685d2ce26d134b64feb50824abb8e","library_file_id":"libfile_8903da570ab48191ad8df88cbba4b6ce","pages":12,"physical_page":9,"block":2,"release":"20261005-clean-notes","decision":"Complete wording, choices and independently solved answer confirmed from clean source."}}},{"id":"dc96305d-be90-53be-af44-6376cb2e18a6","before_hash":"a6998a079055656cde9ac3b08ee306fd","before_question":{"id":"dc96305d-be90-53be-af44-6376cb2e18a6","stem":"Line k is defined by y = 7x + 1/8. Line j is perpendicular to line k in the xy-plane. What is the slope of line j?","type":"mcq","topic":"Linear functions and slope","assets":{"source":"teacher_uploaded_notes_20261005","source_item":1,"source_page":10,"answer_review":"2026-10-05-independent-solution-and-image-check","release_batch":"20261005_uploaded_notes_est_bank","source_sha256":"c8866e74eb87ce3401c5e3bd6ea7a7717f889dc70ec6398eedc2d0e89e4ed62c","lesson_subtopic":"Perpendicular slopes","source_document":"Notes_261005_140129.pdf","verified_release":"20261005_uploaded_notes_est_bank","curriculum_lesson":"Linear functions and slope","verification_note":"Transcribed from the uploaded page image; independently solved. The student-facing stem preserves all needed source givens.","lesson_original_topic":"Linear functions and slope","lesson_taxonomy_version":"20260929"},"choices":[{"key":"A","text":"−8"},{"key":"B","text":"−1/7"},{"key":"C","text":"1/8"},{"key":"D","text":"7"}],"track_id":"est","created_at":"2026-10-05T12:13:59.985454+00:00","difficulty":"easy"},"before_key":{"question_id":"dc96305d-be90-53be-af44-6376cb2e18a6","correct":"B","explanation":"Line k has slope 7. A perpendicular line has slope equal to the negative reciprocal, −1/7."},"stem":"Line k is defined by y = 7x + 1/8. Line j is perpendicular to line k in the xy-plane. What is the slope of line j?","asset_patch":{"clean_source_evidence":{"file":"Notes_261005_145856.pdf","sha256":"1e6cf0ca15d3f96ff5491f27decb93ec3bf685d2ce26d134b64feb50824abb8e","library_file_id":"libfile_8903da570ab48191ad8df88cbba4b6ce","pages":12,"physical_page":10,"block":1,"release":"20261005-clean-notes","decision":"Complete wording, choices and independently solved answer confirmed from clean source."}}},{"id":"e1c96638-70fb-5b2b-95e4-3e9fb5a0dbfe","before_hash":"604f7cde99b0794db189941d9b867d21","before_question":{"id":"e1c96638-70fb-5b2b-95e4-3e9fb5a0dbfe","stem":"A rectangle has an area of 155 square inches. Its length is 4 inches less than 7 times its width. What is the width, in inches?\nRecord your answer as a number.","type":"grid_in","topic":"Quadratics and polynomials","assets":{"source":"teacher_uploaded_notes_20261005","source_item":1,"source_page":9,"answer_review":"2026-10-05-independent-solution-and-image-check","release_batch":"20261005_uploaded_notes_est_bank","source_sha256":"c8866e74eb87ce3401c5e3bd6ea7a7717f889dc70ec6398eedc2d0e89e4ed62c","lesson_subtopic":"Quadratic modeling","source_document":"Notes_261005_140129.pdf","verified_release":"20261005_uploaded_notes_est_bank","curriculum_lesson":"Quadratics and polynomials","verification_note":"Transcribed from the uploaded page image; independently solved. The student-facing stem preserves all needed source givens.","lesson_original_topic":"Quadratics and polynomials","lesson_taxonomy_version":"20260929"},"choices":[],"track_id":"est","created_at":"2026-10-05T12:13:59.985454+00:00","difficulty":"medium"},"before_key":{"question_id":"e1c96638-70fb-5b2b-95e4-3e9fb5a0dbfe","correct":"5","explanation":"Let w be the width. Then w(7w−4)=155, so 7w²−4w−155=0. The discriminant is 4²+4·7·155=4356=66². The positive root is (4+66)/14=5; the negative root is not a possible width."},"stem":"A rectangle has an area of 155 square inches. Its length is 4 inches less than 7 times its width. What is the width, in inches?\nRecord your answer as a number.","asset_patch":{"clean_source_evidence":{"file":"Notes_261005_145856.pdf","sha256":"1e6cf0ca15d3f96ff5491f27decb93ec3bf685d2ce26d134b64feb50824abb8e","library_file_id":"libfile_8903da570ab48191ad8df88cbba4b6ce","pages":12,"physical_page":9,"block":1,"release":"20261005-clean-notes","decision":"Complete wording, choices and independently solved answer confirmed from clean source."}}},{"id":"e7ef8a6a-3155-57ad-ae60-fda29c2e525a","before_hash":"c30683d28e3cc885363b04dde1d428a3","before_question":{"id":"e7ef8a6a-3155-57ad-ae60-fda29c2e525a","stem":"In the xy-plane, the line through (3, m) and (m, 12) passes through the origin. Which value could m be?","type":"mcq","topic":"Linear functions and slope","assets":{"source":"teacher_uploaded_notes_20261005","source_item":2,"source_page":5,"answer_review":"2026-10-05-independent-solution-and-image-check","release_batch":"20261005_uploaded_notes_est_bank","source_sha256":"c8866e74eb87ce3401c5e3bd6ea7a7717f889dc70ec6398eedc2d0e89e4ed62c","lesson_subtopic":"Lines through the origin","source_document":"Notes_261005_140129.pdf","verified_release":"20261005_uploaded_notes_est_bank","curriculum_lesson":"Linear functions and slope","verification_note":"Transcribed from the uploaded page image; independently solved. The student-facing stem preserves all needed source givens.","lesson_original_topic":"Linear functions and slope","lesson_taxonomy_version":"20260929"},"choices":[{"key":"A","text":"−6"},{"key":"B","text":"9"},{"key":"C","text":"1"},{"key":"D","text":"0"}],"track_id":"est","created_at":"2026-10-05T12:13:59.985454+00:00","difficulty":"medium"},"before_key":{"question_id":"e7ef8a6a-3155-57ad-ae60-fda29c2e525a","correct":"A","explanation":"Since the line passes through the origin, the slopes from the origin to both listed points are equal: m/3=12/m. Thus m²=36, so m=±6. Of the choices, only −6 is listed."},"stem":"In the xy-plane, the line through (3, m) and (m, 12) passes through the origin. Which value could m be?","asset_patch":{"clean_source_evidence":{"file":"Notes_261005_145856.pdf","sha256":"1e6cf0ca15d3f96ff5491f27decb93ec3bf685d2ce26d134b64feb50824abb8e","library_file_id":"libfile_8903da570ab48191ad8df88cbba4b6ce","pages":12,"physical_page":5,"block":2,"release":"20261005-clean-notes","decision":"Source-equivalent duplicate; retain original ID/key/history under hold."},"release_hold_reason":"Duplicate of reviewed question 85e6d3ea-8ba1-525c-adaa-0863635ce1c8","duplicate_of":"85e6d3ea-8ba1-525c-adaa-0863635ce1c8"}},{"id":"fade939d-a933-5a95-8448-84620f6bc435","before_hash":"85134646689acb40e96b8121a2e0c912","before_question":{"id":"fade939d-a933-5a95-8448-84620f6bc435","stem":"The table gives several points on the graph of the quadratic function q(x).\n\nx: −5, −3, −1, 1, 3, 5\nq(x): −7, −15, −15, −7, 9, 33\n\nWhat is q(−9)?\nRecord your answer as a number.","type":"grid_in","topic":"Quadratics and polynomials","assets":{"source":"teacher_uploaded_notes_20261005","source_item":1,"source_page":4,"answer_review":"2026-10-05-independent-solution-and-image-check","release_batch":"20261005_uploaded_notes_est_bank","source_sha256":"c8866e74eb87ce3401c5e3bd6ea7a7717f889dc70ec6398eedc2d0e89e4ed62c","lesson_subtopic":"Quadratic functions and tables","source_document":"Notes_261005_140129.pdf","verified_release":"20261005_uploaded_notes_est_bank","curriculum_lesson":"Quadratics and polynomials","verification_note":"Transcribed from the uploaded page image; independently solved. The student-facing stem preserves all needed source givens.","lesson_original_topic":"Quadratics and polynomials","lesson_taxonomy_version":"20260929"},"choices":[],"track_id":"est","created_at":"2026-10-05T12:13:59.985454+00:00","difficulty":"medium"},"before_key":{"question_id":"fade939d-a933-5a95-8448-84620f6bc435","correct":"33","explanation":"The first differences for a step of 2 are −8, 0, 8, 16, 24, so the constant second difference is 8 and the leading coefficient is 1. The values fit q(x)=x²+4x−12. Therefore q(−9)=81−36−12=33."},"stem":"The table shows points from a quadratic function q. What is q(-9)?\n\n\\(\\begin{array}{c|rrrrrr}x&-5&-3&-1&1&3&5\\\\\\hline q(x)&-7&-15&-15&-7&9&33\\end{array}\\)","asset_patch":{"clean_source_evidence":{"file":"Notes_261005_145856.pdf","sha256":"1e6cf0ca15d3f96ff5491f27decb93ec3bf685d2ce26d134b64feb50824abb8e","library_file_id":"libfile_8903da570ab48191ad8df88cbba4b6ce","pages":12,"physical_page":4,"block":1,"release":"20261005-clean-notes","decision":"Complete wording, choices and independently solved answer confirmed from clean source."}}},{"id":"fe364c75-f5c4-5da8-aeea-09e9538d97c7","before_hash":"abba83322b3e754350011277d6bebd57","before_question":{"id":"fe364c75-f5c4-5da8-aeea-09e9538d97c7","stem":"Figure 8 shows rectangle ABCD. Points A and D lie on the parabola y = 2x² − 8, and points B and C lie on the parabola y = 9 − x². If B has coordinates (−1.50, 6.75), what is the area of rectangle ABCD?","type":"mcq","topic":"Quadratics and polynomials","assets":{"figure":"data:image/svg+xml;base64,","source":"teacher_uploaded_notes_20261005","image_alt":"Rectangle with vertical sides at x = −1.5 and x = 1.5 between y = 9 − x² and y = 2x² − 8.","source_item":1,"source_page":2,"answer_review":"2026-10-05-independent-solution-and-image-check","release_batch":"20261005_uploaded_notes_est_bank","source_sha256":"c8866e74eb87ce3401c5e3bd6ea7a7717f889dc70ec6398eedc2d0e89e4ed62c","figure_caption":"Rectangle with vertical sides at x = −1.5 and x = 1.5 between y = 9 − x² and y = 2x² − 8.","lesson_subtopic":"Parabolas and applications","source_document":"Notes_261005_140129.pdf","verified_release":"20261005_uploaded_notes_est_bank","curriculum_lesson":"Quadratics and polynomials","verification_note":"Transcribed from the uploaded page image; independently solved. The student-facing stem preserves all needed source givens.","lesson_original_topic":"Quadratics and polynomials","lesson_taxonomy_version":"20260929"},"choices":[{"key":"A","text":"12.50"},{"key":"B","text":"17.50"},{"key":"C","text":"22.75"},{"key":"D","text":"26.50"},{"key":"E","text":"30.75"}],"track_id":"est","created_at":"2026-10-05T12:13:59.985454+00:00","difficulty":"medium"},"before_key":{"question_id":"fe364c75-f5c4-5da8-aeea-09e9538d97c7","correct":"E","explanation":"Because the parabolas are symmetric about the y-axis, the rectangle’s vertical sides have x-coordinates −1.5 and 1.5, so its width is 3. The upper y-coordinate is 6.75. The lower y-coordinate is 2(1.5)²−8=−3.5. Its height is 10.25, so its area is 3×10.25=30.75."},"stem":"Figure 8 shows rectangle ABCD. Points A and D lie on the parabola y = 2x² − 8, and points B and C lie on the parabola y = 9 − x². If B has coordinates (−1.50, 6.75), what is the area of rectangle ABCD?","asset_patch":{"clean_source_evidence":{"file":"Notes_261005_145856.pdf","sha256":"1e6cf0ca15d3f96ff5491f27decb93ec3bf685d2ce26d134b64feb50824abb8e","library_file_id":"libfile_8903da570ab48191ad8df88cbba4b6ce","pages":12,"physical_page":2,"block":1,"release":"20261005-clean-notes","decision":"Complete wording, choices and independently solved answer confirmed from clean source."},"figure":"data:image/png;base64,","figure_caption":"Original supplied Figure 8 (schematic, not to scale).","source_figure_crop":[165,16,375,260],"source_figure_sha256":"c94826e7e7cfea792221341eaed0c101c6a849704253e2c7e6ee12ac6ff286e1"}}],"inserts":[{"id":"a187283a-81bd-5f53-be06-afed103d200a","track_id":"est","topic":"Exponents, radicals and growth","difficulty":"hard","type":"mcq","stem":"Which listed value approximates a real solution n of \\(\\dfrac{3^{(n-1)^4}\\times9^{2n}}{3^7}=81\\)?","choices":[{"key":"A","text":"-0.661"},{"key":"B","text":"-0.96"},{"key":"C","text":"-1.23"},{"key":"D","text":"3.78"}],"correct":"B","explanation":"Since 9^(2n)=3^(4n) and 81=3^4, the equation is (n-1)^4+4n-11=0. Its two real roots are approximately -0.963135087 and 2.211478586. The negative root rounds to -0.96, the only matching listed choice. Multiple real solutions do not invalidate the unique listed approximation.","assets":{"source":"Instructor-supplied EST & SAT Math notes, 5 October 2026","source_id":"clean-notes-20261005","source_question_id":"clean-notes-20261005-p3-b1","source_page":3,"source_block":1,"source_document":"Notes_261005_145856.pdf","source_library_id":"libfile_8903da570ab48191ad8df88cbba4b6ce","source_file_sha256":"1e6cf0ca15d3f96ff5491f27decb93ec3bf685d2ce26d134b64feb50824abb8e","curriculum_lesson":"Exponents, radicals and growth","lesson_subtopic":"Equating exponents and solving a quartic numerically","lesson_taxonomy_version":"20260929","answer_review":"20261005-independent-solution-clean-notes","verified_release":"20261005-clean-notes","mathematical_review_scope":"Complete supplied stem and all visible choices independently solved; source has no printed answer key.","source_original_stem":"Find the value of n in the equation","source_wording_adjustment":"Explicitly says approximates a real solution because the supplied finite-decimal choices are approximate, not exact roots. Equation and choices unchanged."}},{"id":"02d35679-8918-56e7-8ef7-572550ac042c","track_id":"est","topic":"Ratios, percentages and unit conversion","difficulty":"easy","type":"mcq","stem":"If a:b=2:5 and b:c=3:4, what is a:c?","choices":[{"key":"A","text":"3:10"},{"key":"B","text":"2:4"},{"key":"C","text":"6:15"},{"key":"D","text":"8:15"}],"correct":"A","explanation":"Make b=15 in both ratios: a:b=6:15 and b:c=15:20. Thus a:c=6:20=3:10. Choice C is 6:15=2:5 and is not equivalent to 3:10.","assets":{"source":"Instructor-supplied EST & SAT Math notes, 5 October 2026","source_id":"clean-notes-20261005","source_question_id":"clean-notes-20261005-p11-b3","source_page":11,"source_block":3,"source_document":"Notes_261005_145856.pdf","source_library_id":"libfile_8903da570ab48191ad8df88cbba4b6ce","source_file_sha256":"1e6cf0ca15d3f96ff5491f27decb93ec3bf685d2ce26d134b64feb50824abb8e","curriculum_lesson":"Ratios, percentages and unit conversion","lesson_subtopic":"Combining ratios with a common term","lesson_taxonomy_version":"20260929","answer_review":"20261005-independent-solution-clean-notes","verified_release":"20261005-clean-notes","mathematical_review_scope":"Complete supplied stem and all visible choices independently solved; source has no printed answer key."}}],"source":{"file":"Notes_261005_145856.pdf","sha256":"1e6cf0ca15d3f96ff5491f27decb93ec3bf685d2ce26d134b64feb50824abb8e","library_file_id":"libfile_8903da570ab48191ad8df88cbba4b6ce","pages":12}}$payload$::jsonb;p jsonb;affected uuid[];inserted_ids uuid[]='{}';before_hash text;after_hash text;qh text;
begin
 perform pg_advisory_xact_lock(hashtextextended('20261005-clean-notes',0));
 if exists(select 1 from public.audit_log where action='question.clean_notes_20261005') then raise exception 'Clean source reconciliation already applied'; end if;
 select md5(string_agg(md5(jsonb_build_array(to_jsonb(q),to_jsonb(k))::text),'' order by q.id)) from public.questions q left join public.question_keys k on k.question_id=q.id where q.track_id='est' into qh;
 if qh is distinct from '99b9540f154173090c429bc94d716c05' then raise exception 'EST I bank changed since full duplicate review'; end if;
 select array_agg((value->>'id')::uuid) into affected from jsonb_array_elements(packet->'patches');
 -- All reconciled records must still be unused: no assessment/history is rewritten.
 lock table public.exams,public.revision_items in share mode;
 if exists(select 1 from public.exams where question_ids && affected) or exists(select 1 from public.revision_items where question_id=any(affected)) then raise exception 'Imported record now used by assessment/revision; re-review before changing'; end if;
 select md5(string_agg(md5(jsonb_build_array(to_jsonb(q),to_jsonb(k))::text),'' order by q.id)) from public.questions q left join public.question_keys k on k.question_id=q.id where q.track_id='est' and not(q.id=any(affected)) into before_hash;
 for p in select value from jsonb_array_elements(packet->'patches') loop
  select md5(jsonb_build_array(to_jsonb(q),to_jsonb(k))::text) into qh from public.questions q left join public.question_keys k on k.question_id=q.id where q.id=(p->>'id')::uuid;
  if qh is distinct from p->>'before_hash' then raise exception 'Concurrent imported record change: %',p->>'id'; end if;
  update public.questions set stem=p->>'stem',assets=assets||(p->'asset_patch') where id=(p->>'id')::uuid;
  if not exists(select 1 from public.questions q join public.question_keys k on k.question_id=q.id where q.id=(p->>'id')::uuid
   and (to_jsonb(q)-'stem'-'assets')=((p->'before_question')-'stem'-'assets') and to_jsonb(k)=p->'before_key') then raise exception 'Question identity, choices or key changed'; end if;
  insert into public.audit_log(action,target_type,target_id,meta) values('question.clean_notes_source_20261005','question',p->>'id',jsonb_build_object('before_question',p->'before_question','source',packet->'source','key_unchanged',true));
 end loop;
 for p in select value from jsonb_array_elements(packet->'inserts') loop
  if exists(select 1 from public.questions where id=(p->>'id')::uuid or assets->>'source_question_id'=p->'assets'->>'source_question_id') then raise exception 'Candidate already present'; end if;
  if exists(select 1 from public.questions where track_id='est' and lower(regexp_replace(stem,'[^[:alnum:]]','','g'))=lower(regexp_replace(p->>'stem','[^[:alnum:]]','','g'))) then raise exception 'Duplicate stem'; end if;
  if p->>'track_id'<>'est' or nullif(p->>'explanation','') is null or p->'correct' is null
   or not exists(select 1 from jsonb_array_elements(p->'choices') c where c->>'key'=p->>'correct') then raise exception 'Invalid candidate'; end if;
  insert into public.questions(id,track_id,topic,difficulty,type,stem,choices,assets) values((p->>'id')::uuid,'est',p->>'topic',p->>'difficulty',p->>'type',p->>'stem',p->'choices',p->'assets');
  insert into public.question_keys(question_id,correct,explanation) values((p->>'id')::uuid,p->'correct',p->>'explanation');
  inserted_ids:=array_append(inserted_ids,(p->>'id')::uuid);
 end loop;
 if cardinality(inserted_ids)<>2 or cardinality(affected)<>14 then raise exception 'Unexpected packet count'; end if;
 select md5(string_agg(md5(jsonb_build_array(to_jsonb(q),to_jsonb(k))::text),'' order by q.id)) from public.questions q left join public.question_keys k on k.question_id=q.id where q.track_id='est' and not(q.id=any(affected||inserted_ids)) into after_hash;
 if after_hash is distinct from before_hash then raise exception 'Unrelated question/key changed'; end if;
 insert into public.audit_log(action,target_type,target_id,meta) values('question.clean_notes_20261005','question_batch','20261005-clean-notes',jsonb_build_object('reconciled_count',14,'inserted_ids',to_jsonb(inserted_ids),'inserted_count',2,'imported_duplicates_held',4,'source_sha256','1e6cf0ca15d3f96ff5491f27decb93ec3bf685d2ce26d134b64feb50824abb8e','unrelated_records_preserved',true));
end $release$;
